import { monitoredEntitiesClient } from '@dynatrace-sdk/client-classic-environment-v2';

export default async function () {
  const groups = [];
  try {
    let nextPageKey;
    do {
      const page = await monitoredEntitiesClient.getEntities(
        nextPageKey ? { nextPageKey } : { entitySelector: 'type(HOST_GROUP)', pageSize: 500 }
      );
      for (const e of page.entities ?? []) groups.push({ entityId: e.entityId, name: e.displayName });
      nextPageKey = page.nextPageKey;
    } while (nextPageKey);
    return { groups };
  } catch (e) {
    return { groups, error: String(e?.message ?? e) };
  }
}

import { execution } from '@dynatrace-sdk/automation-utils';
import { settingsObjectsClient } from '@dynatrace-sdk/client-classic-environment-v2';

const SCHEMA = 'builtin:ingest.enrichment.config';
const TARGET = 'primary_tags.AppID';
const q = (s) => s.replace(/\\/g, '\\\\').replace(/"/g, '\\"');

export default async function ({ execution_id }) {
  const ex = await execution(execution_id);
  // Union of three discovery sources; a failed source contributes nothing
  const safe = async (id) => { try { return await ex.result(id); } catch { return null; } };
  const names = new Set();
  const metrics = await safe('get_host_groups');
  for (const r of metrics?.records ?? []) names.add(r['dt.host_group.id']);
  const classic = await safe('get_host_groups_classic');
  for (const r of classic?.groups ?? []) names.add(r.name);
  const smart = await safe('get_host_groups_smartscape');
  for (const r of smart?.records ?? []) names.add(r.name);
  const sources = {
    metrics: metrics?.records?.length ?? null,
    classic: classic?.error ? `error: ${classic.error}` : (classic?.groups?.length ?? null),
    smartscape: smart?.records?.length ?? null,
  };
  const groups = [...names].filter(Boolean).map((n) => ({ 'dt.host_group.id': n }));

  // Existing AppID rules at environment scope, keyed by condition
  const existing = new Map();
  let nextPageKey;
  do {
    const page = await settingsObjectsClient.getSettingsObjects(
      nextPageKey ? { nextPageKey } : { schemaIds: SCHEMA, scopes: 'environment', fields: 'objectId,scope,value', pageSize: 500 }
    );
    for (const o of page.items ?? []) if (o.value?.target === TARGET && o.value?.condition) existing.set(o.value.condition, o);
    nextPageKey = page.nextPageKey;
  } while (nextPageKey);

  const created = [], updated = [], skipped = [], failed = [];
  for (const g of groups) {
    const hostGroup = g['dt.host_group.id'];
    // Host group pattern 100144_ACL_MOD -> AppID 100144
    const m = /^(\d+)_/.exec(hostGroup ?? '');
    if (!m) { skipped.push(hostGroup); continue; }
    const appId = m[1];
    const condition = `matchesValue(dt.host_group.id, "${q(hostGroup)}")`;
    const value = { type: 'CUSTOM', valueSource: appId, target: TARGET, condition };
    try {
      const cur = existing.get(condition);
      if (cur && cur.value.valueSource === appId) continue;
      if (cur) {
        await settingsObjectsClient.putSettingsObjectByObjectId({ objectId: cur.objectId, body: { value } });
        updated.push(hostGroup);
      } else {
        await settingsObjectsClient.postSettingsObjects({ body: [{ schemaId: SCHEMA, scope: 'environment', value }] });
        created.push(`${hostGroup} -> ${appId}`);
      }
    } catch (e) {
      failed.push({ hostGroup, error: String(e?.message ?? e) });
    }
  }
  if (failed.length) throw new Error('Some rules failed: ' + JSON.stringify(failed));
  return { sources, created, updated, skipped, total: groups.length };
}
